  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perhatikan reaksi: 2SO₂(g) + O₂(g) ⇌ 2SO₃(g). Jika tekanan sistem diperbesar, maka kesetimbangan akan...','[{"key": "A", "text": "Bergeser ke kiri karena jumlah mol reaktan lebih besar"}, {"key": "B", "text": "Bergeser ke kanan karena jumlah mol produk lebih kecil"}, {"key": "C", "text": "Tidak bergeser karena fasa semua zat sama"}, {"key": "D", "text": "Bergeser ke arah reaksi endoterm"}]'::jsonb,'B','Sesuai Asas Le Chatelier, jika tekanan suatu sistem kesetimbangan gas diperbesar, kesetimbangan akan bergeser ke sisi dengan jumlah mol gas yang lebih kecil. Di sisi reaktan, jumlah mol gas adalah 2 (dari SO₂) + 1 (dari O₂) = 3 mol. Di sisi produk, jumlah mol gas adalah 2 (dari SO₃). Karena sisi produk memiliki mol lebih kecil, kesetimbangan bergeser ke kanan.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pembakaran tidak sempurna bahan bakar hidrokarbon dari mesin kendaraan bermotor menghasilkan gas yang sangat beracun, yaitu...','[{"key": "A", "text": "Karbon dioksida (CO₂)"}, {"key": "B", "text": "Sulfur dioksida (SO₂)"}, {"key": "C", "text": "Nitrogen dioksida (NO₂)"}, {"key": "D", "text": "Karbon monoksida (CO)"}]'::jsonb,'D','Pembakaran tidak sempurna terjadi ketika pasokan oksigen tidak mencukupi untuk mengubah seluruh karbon dalam bahan bakar menjadi karbon dioksida (CO₂). Akibatnya, terbentuklah karbon monoksida (CO), gas yang tidak berwarna, tidak berbau, dan sangat beracun karena dapat mengikat hemoglobin dalam darah lebih kuat daripada oksigen.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam reaksi produksi gas buang di Pembangkit Listrik Tenaga Uap (PLTU) berbahan bakar batu bara, unsur sulfur (S) dalam batu bara akan bereaksi dengan oksigen membentuk...','[{"key": "A", "text": "SO₂"}, {"key": "B", "text": "H₂S"}, {"key": "C", "text": "CS₂"}, {"key": "D", "text": "H₂SO₄"}]'::jsonb,'A','Batu bara seringkali mengandung sulfur sebagai pengotor. Selama proses pembakaran pada suhu tinggi di PLTU, sulfur (S) ini akan bereaksi dengan oksigen (O₂) dari udara membentuk gas sulfur dioksida (SO₂), yang merupakan polutan udara utama.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tetapan kesetimbangan (Kc) untuk reaksi H₂(g) + I₂(g) ⇌ 2HI(g) diberikan oleh persamaan...','[{"key": "A", "text": "Kc = [H₂][I₂] / [HI]²"}, {"key": "B", "text": "Kc = [HI] / ([H₂][I₂])"}, {"key": "C", "text": "Kc = [HI]² / ([H₂][I₂])"}, {"key": "D", "text": "Kc = [2HI] / ([H₂][I₂])"}]'::jsonb,'C','Tetapan kesetimbangan konsentrasi (Kc) didefinisikan sebagai rasio dari hasil kali konsentrasi produk terhadap hasil kali konsentrasi reaktan, dengan setiap konsentrasi dipangkatkan sesuai koefisien stoikiometrinya. Untuk reaksi H₂(g) + I₂(g) ⇌ 2HI(g), produknya adalah HI dengan koefisien 2, sehingga bagian atas (pembilang) dari persamaan adalah [HI]². Reaktannya adalah H₂ dan I₂ yang masing-masing memiliki koefisien 1, sehingga bagian bawah (penyebut) adalah [H₂][I₂]. Dengan demikian, ekspresi yang benar adalah Kc = [HI]² / ([H₂][I₂]).','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah reaksi kimia dikatakan mencapai kesetimbangan dinamis ketika...','[{"key": "A", "text": "Reaksi telah berhenti total"}, {"key": "B", "text": "Laju reaksi ke arah produk sama dengan laju reaksi ke arah reaktan"}, {"key": "C", "text": "Konsentrasi reaktan telah habis"}, {"key": "D", "text": "Suhu dan tekanan sistem menjadi nol"}]'::jsonb,'B','Kesetimbangan kimia disebut dinamis karena reaksi tidak berhenti. Reaksi pembentukan produk (reaksi maju) dan reaksi penguraian produk kembali menjadi reaktan (reaksi balik) terus terjadi, namun dengan laju yang sama. Akibatnya, tidak ada perubahan yang teramati pada konsentrasi zat-zat tersebut.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perubahan entalpi (ΔH) untuk reaksi eksoterm memiliki nilai...','[{"key": "A", "text": "Positif"}, {"key": "B", "text": "Negatif"}, {"key": "C", "text": "Nol"}, {"key": "D", "text": "Sama dengan energi aktivasi"}]'::jsonb,'B','Pernyataan ini dikenal sebagai Hukum Kekekalan Energi, yang merupakan prinsip dasar dari Hukum Pertama Termodinamika. Energi total di alam semesta adalah konstan.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hukum Pertama Termodinamika menyatakan bahwa...','[{"key": "A", "text": "Entropi semesta selalu meningkat"}, {"key": "B", "text": "Energi tidak dapat diciptakan atau dimusnahkan, hanya dapat diubah bentuknya"}, {"key": "C", "text": "Reaksi spontan selalu melepaskan panas"}, {"key": "D", "text": "Tidak mungkin membuat mesin dengan efisiensi 100%"}]'::jsonb,'C','Entropi (dilambangkan dengan S) adalah besaran termodinamika yang mengukur tingkat ketidakteraturan atau keacakan molekul dalam suatu sistem. Semakin tidak teratur suatu sistem (misalnya, gas lebih tidak teratur daripada padatan), semakin tinggi nilai entropinya.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ukuran ketidakteraturan atau keacakan dalam suatu sistem termodinamika disebut...','[{"key": "A", "text": "Entalpi"}, {"key": "B", "text": "Energi bebas Gibbs"}, {"key": "C", "text": "Entropi"}, {"key": "D", "text": "Kalor"}]'::jsonb,'B','Proses pembakaran bahan bakar secara definisi adalah reaksi kimia yang melepaskan sejumlah besar energi ke lingkungan dalam bentuk panas dan cahaya. Oleh karena itu, reaksi ini bersifat eksoterm.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses pembakaran di dalam mesin PLTU merupakan contoh reaksi...','[{"key": "A", "text": "Endoterm, karena membutuhkan panas untuk memulai"}, {"key": "B", "text": "Eksoterm, karena melepaskan energi panas yang besar"}, {"key": "C", "text": "Isotermal, karena suhunya dijaga konstan"}, {"key": "D", "text": "Spontan pada semua suhu"}]'::jsonb,'C','Efisiensi pembakaran justru memerlukan suhu yang cukup tinggi untuk memastikan reaksi berlangsung dengan cepat dan sempurna. Menurunkan suhu akan memperlambat laju reaksi dan berpotensi menyebabkan pembakaran tidak sempurna, sehingga menurunkan efisiensi.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Efisiensi pembakaran dapat ditingkatkan dengan cara, kecuali...','[{"key": "A", "text": "Memastikan pasokan oksigen yang cukup"}, {"key": "B", "text": "Meningkatkan luas permukaan kontak bahan bakar"}, {"key": "C", "text": "Mengurangi suhu pembakaran secara drastis"}, {"key": "D", "text": "Menggunakan katalis yang sesuai"}]'::jsonb,'B','Hukum Kedua Termodinamika menyatakan bahwa semua proses spontan atau alami akan selalu bergerak menuju keadaan dengan entropi (ketidakteraturan) yang lebih tinggi. Dengan kata lain, entropi alam semesta selalu bertambah.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pernyataan yang sesuai dengan Hukum Kedua Termodinamika adalah...','[{"key": "A", "text": "Kalor mengalir secara spontan dari benda dingin ke benda panas"}, {"key": "B", "text": "Total entropi dari sistem terisolasi cenderung meningkat seiring waktu"}, {"key": "C", "text": "Energi dalam sistem terisolasi adalah konstan"}, {"key": "D", "text": "Semua proses di alam semesta bersifat reversibel"}]'::jsonb,'A','Kespontanan reaksi ditentukan oleh Energi Bebas Gibbs (ΔG = ΔH - TΔS). Jika perubahan entalpi (ΔH) negatif (eksoterm) dan perubahan entropi (ΔS) positif (semakin acak), maka suku "-TΔS" akan selalu negatif. Hasil penjumlahan dua nilai negatif (ΔH dan -TΔS) akan selalu menghasilkan ΔG yang negatif, yang berarti reaksi tersebut spontan pada suhu berapapun (selama T dalam Kelvin > 0).','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika suatu reaksi memiliki ΔH negatif dan ΔS positif, maka reaksi tersebut...','[{"key": "A", "text": "Spontan pada semua suhu"}, {"key": "B", "text": "Tidak spontan pada semua suhu"}, {"key": "C", "text": "Spontan hanya pada suhu tinggi"}, {"key": "D", "text": "Spontan hanya pada suhu rendah"}]'::jsonb,'C','Berdasarkan konvensi internasional, nilai entalpi pembentukan standar (ΔH°f) untuk setiap unsur dalam bentuknya yang paling stabil pada kondisi standar (25 °C dan 1 atm) ditetapkan sebagai nol. Contohnya adalah O₂(gas), C(grafit), dan Fe(padat).','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Entalpi pembentukan standar (ΔH°f) suatu unsur dalam bentuknya yang paling stabil pada keadaan standar adalah...','[{"key": "A", "text": "Selalu positif"}, {"key": "B", "text": "Selalu negatif"}, {"key": "C", "text": "Nol"}, {"key": "D", "text": "Tergantung pada unsurnya"}]'::jsonb,'B','Timbulnya panas saat NaOH dilarutkan menunjukkan bahwa sistem (larutan) melepaskan energi ke lingkungan. Proses pelepasan energi ini adalah karakteristik dari reaksi atau proses yang bersifat eksoterm.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Reaksi panas yang terjadi saat melarutkan NaOH padat ke dalam air menunjukkan bahwa proses pelarutan tersebut bersifat...','[{"key": "A", "text": "Endoterm"}, {"key": "B", "text": "Eksoterm"}, {"key": "C", "text": "Isoentropi"}, {"key": "D", "text": "Adiabatik"}]'::jsonb,'C','Energi Bebas Gibbs (ΔG) adalah parameter termodinamika yang paling tepat untuk menentukan apakah suatu reaksi dapat berlangsung secara spontan pada suhu dan tekanan konstan. Jika nilai ΔG negatif, reaksi tersebut spontan.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Energi Bebas Gibbs (ΔG) digunakan untuk memprediksi...','[{"key": "A", "text": "Laju reaksi"}, {"key": "B", "text": "Panas yang dilepaskan"}, {"key": "C", "text": "Kespontanan suatu reaksi"}, {"key": "D", "text": "Perubahan volume sistem"}]'::jsonb,'B','BOD (Biochemical Oxygen Demand) adalah ukuran jumlah oksigen terlarut yang dikonsumsi oleh mikroorganisme aerobik saat mereka menguraikan bahan organik yang dapat terurai (biodegradable) dalam sampel air.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'BOD (Biochemical Oxygen Demand) adalah parameter yang mengukur...','[{"key": "A", "text": "Jumlah total padatan terlarut dalam air"}, {"key": "B", "text": "Jumlah oksigen yang dibutuhkan oleh mikroorganisme untuk menguraikan bahan organik"}, {"key": "C", "text": "Jumlah bahan kimia oksidator yang dibutuhkan untuk mengoksidasi semua zat di air"}, {"key": "D", "text": "Tingkat keasaman atau pH air limbah"}]'::jsonb,'B','Proses anaerobik adalah proses penguraian bahan organik oleh mikroorganisme yang hidup dan bekerja tanpa kehadiran oksigen bebas. Proses ini sering digunakan dalam pengolahan lumpur limbah dan menghasilkan biogas.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah yang nilainya selalu lebih tinggi atau sama untuk sampel air limbah yang sama?','[{"key": "A", "text": "BOD lebih tinggi dari COD"}, {"key": "B", "text": "COD lebih tinggi dari BOD"}, {"key": "C", "text": "BOD dan COD selalu sama"}, {"key": "D", "text": "Tergantung jenis limbahnya"}]'::jsonb,'D','Osmosis terbalik adalah proses pemurnian air yang menggunakan tekanan untuk mendorong air melewati membran semipermeabel. Membran ini memiliki pori-pori yang sangat kecil sehingga dapat menahan molekul besar seperti ion garam, tetapi membiarkan molekul air melewatinya.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses pengolahan air limbah yang menggunakan mikroorganisme tanpa adanya oksigen terlarut disebut proses...','[{"key": "A", "text": "Aerobik"}, {"key": "B", "text": "Anaerobik"}, {"key": "C", "text": "Fakultatif"}, {"key": "D", "text": "Filtrasi"}]'::jsonb,'C','Pengolahan primer adalah tahap awal yang berfokus pada proses fisika. Tujuannya adalah untuk menghilangkan padatan kasar dan benda-benda yang mudah dipisahkan melalui penyaringan (screening) dan pengendapan di bak sedimentasi.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Teknologi membran yang digunakan untuk menghilangkan garam terlarut dari air laut dalam proses desalinasi adalah...','[{"key": "A", "text": "Mikrofiltrasi"}, {"key": "B", "text": "Ultrafiltrasi"}, {"key": "C", "text": "Nanofiltrasi"}, {"key": "D", "text": "Osmosis terbalik (Reverse Osmosis)"}]'::jsonb,'C','Proses lumpur aktif adalah metode pengolahan air limbah secara biologis yang paling umum. Proses ini melibatkan pembiakan mikroorganisme dalam tangki yang diaerasi (diberi oksigen) untuk menguraikan polutan organik terlarut.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari tahap pengolahan primer (primary treatment) pada instalasi pengolahan air limbah (IPAL) adalah...','[{"key": "A", "text": "Menghilangkan senyawa organik terlarut"}, {"key": "B", "text": "Membunuh mikroorganisme patogen"}, {"key": "C", "text": "Menghilangkan padatan tersuspensi dan benda-benda terapung"}, {"key": "D", "text": "Menghilangkan nutrien seperti nitrogen dan fosfor"}]'::jsonb,'C','Filtrasi dengan media granular seperti pasir dan kerikil adalah metode fisik untuk menyaring dan menghilangkan partikel padat halus yang tersuspensi di dalam air, yang tidak dapat dihilangkan secara efektif oleh pengendapan.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Lumpur aktif (activated sludge) adalah contoh dari proses pengolahan limbah secara...','[{"key": "A", "text": "Fisika"}, {"key": "B", "text": "Kimia"}, {"key": "C", "text": "Biologis aerobik"}, {"key": "D", "text": "Biologis anaerobik"}]'::jsonb,'B','Osmosis adalah fenomena alam di mana molekul pelarut (biasanya air) bergerak secara spontan melalui membran semipermeabel dari area dengan konsentrasi zat terlarut yang lebih rendah (larutan encer) ke area dengan konsentrasi zat terlarut yang lebih tinggi (larutan pekat) untuk menyeimbangkan konsentrasi.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Filtrasi menggunakan media pasir dan kerikil bertujuan untuk menghilangkan...','[{"key": "A", "text": "Ion-ion logam berat"}, {"key": "B", "text": "Garam-garam terlarut"}, {"key": "C", "text": "Partikel-partikel tersuspensi"}, {"key": "D", "text": "Bakteri dan virus"}]'::jsonb,'B','Uji COD menggunakan oksidator kimia yang sangat kuat (seperti kalium dikromat dalam medium asam) yang mampu mengoksidasi hampir seluruh senyawa organik, termasuk yang sulit atau tidak bisa diuraikan oleh mikroorganisme, serta beberapa senyawa anorganik tereduksi.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses osmosis alami adalah perpindahan pelarut (air) melalui membran semipermeabel dari...','[{"key": "A", "text": "Larutan pekat ke larutan encer"}, {"key": "B", "text": "Larutan encer ke larutan pekat"}, {"key": "C", "text": "Larutan dengan pH tinggi ke pH rendah"}, {"key": "D", "text": "Larutan dengan suhu tinggi ke suhu rendah"}]'::jsonb,'B','Air yang digunakan dalam sistem PLTU, terutama untuk boiler bertekanan tinggi, harus memiliki tingkat kemurnian yang sangat tinggi. Kandungan mineral (garam terlarut) harus dihilangkan untuk mencegah terbentuknya kerak (scale) pada permukaan perpindahan panas dan untuk menghindari korosi yang dapat merusak peralatan vital.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'COD (Chemical Oxygen Demand) menggunakan oksidator kimia kuat seperti kalium dikromat untuk mengoksidasi...','[{"key": "A", "text": "Hanya bahan organik yang dapat diurai secara biologis"}, {"key": "B", "text": "Hampir semua bahan organik dan beberapa anorganik"}, {"key": "C", "text": "Hanya senyawa anorganik"}, {"key": "D", "text": "Hanya logam berat"}]'::jsonb,'C','Oksida sulfur (SOx) dan oksida nitrogen (NOx) yang dilepaskan ke atmosfer dapat bereaksi dengan uap air, oksigen, dan senyawa kimia lainnya untuk membentuk asam sulfat dan asam nitrat. Asam-asam ini kemudian jatuh ke bumi dalam bentuk hujan, salju, atau kabut, yang dikenal sebagai hujan asam.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pengolahan air di PLTU bertujuan untuk...','[{"key": "A", "text": "Meningkatkan kandungan mineral agar lebih sehat"}, {"key": "B", "text": "Mencegah korosi dan pembentukan kerak pada boiler dan sistem pendingin"}, {"key": "C", "text": "Menjadikannya layak untuk dibuang ke sungai tanpa pengolahan"}, {"key": "D", "text": "Menambah kadar oksigen terlarut untuk biota air"}]'::jsonb,'C','Walaupun gas lain seperti metana memiliki potensi pemanasan global yang lebih tinggi per molekul, volume emisi karbon dioksida dari aktivitas manusia (terutama pembakaran bahan bakar fosil) jauh melampaui gas rumah kaca lainnya, menjadikannya kontributor utama pemanasan global.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Emisi SOx (Sulfur Oksida) dari pembakaran bahan bakar fosil merupakan penyebab utama dari...','[{"key": "A", "text": "Pemanasan global"}, {"key": "B", "text": "Penipisan lapisan ozon"}, {"key": "C", "text": "Hujan asam"}, {"key": "D", "text": "Eutrofikasi"}]'::jsonb,'A','Partikulat dengan diameter aerodinamis 2.5 mikrometer atau lebih kecil (PM2.5) sangat berbahaya karena ukurannya yang sangat kecil memungkinkannya untuk menembus jauh ke dalam saluran pernapasan, mencapai alveoli di paru-paru, dan bahkan masuk ke dalam sirkulasi darah, menyebabkan berbagai masalah kardiovaskular dan pernapasan.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gas rumah kaca utama yang emisinya paling banyak dikontribusikan oleh aktivitas manusia adalah...','[{"key": "A", "text": "Metana (CH₄)"}, {"key": "B", "text": "Dinitrogen oksida (N₂O)"}, {"key": "C", "text": "Karbon dioksida (CO₂)"}, {"key": "D", "text": "Ozon (O₃)"}]'::jsonb,'C','FGD adalah sekelompok teknologi yang dirancang khusus untuk menghilangkan sulfur dioksida (SO₂) dari gas buang (flue gas) yang dihasilkan oleh pembangkit listrik dan industri. Metode yang umum adalah "wet scrubbing", di mana gas buang direaksikan dengan slurry batu kapur. Cyclone dan ESP digunakan untuk mengendalikan partikulat.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'NOx (Nitrogen Oksida) terbentuk pada proses pembakaran ketika...','[{"key": "A", "text": "Nitrogen dari udara bereaksi pada suhu yang sangat tinggi"}, {"key": "B", "text": "Nitrogen dalam bahan bakar teroksidasi"}, {"key": "C", "text": "Terjadi reaksi antara sulfur dengan nitrogen"}, {"key": "D", "text": "A dan B benar"}]'::jsonb,'B','Catalytic converter menggunakan katalis logam mulia (seperti platina dan rodium) untuk mengubah polutan gas buang yang berbahaya menjadi senyawa yang lebih aman. Gas CO dioksidasi menjadi CO₂, hidrokarbon (HC) dioksidasi menjadi CO₂ dan H₂O, dan NOx direduksi menjadi gas nitrogen (N₂).','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Partikulat (Particulate Matter) dengan ukuran PM2.5 sangat berbahaya bagi kesehatan karena...','[{"key": "A", "text": "Dapat masuk hingga ke dalam paru-paru dan aliran darah"}, {"key": "B", "text": "Bersifat sangat korosif"}, {"key": "C", "text": "Menyebabkan iritasi kulit secara langsung"}, {"key": "D", "text": "Dapat merusak bangunan"}]'::jsonb,'B','Metode standar untuk mengestimasi emisi adalah dengan menggunakan faktor emisi, yaitu nilai yang merepresentasikan jumlah polutan yang dilepaskan per unit aktivitas (misalnya, kg SO₂ per ton batu bara yang dibakar). Emisi total dihitung dengan mengalikan faktor ini dengan total aktivitas selama periode tertentu.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu teknologi untuk mitigasi atau mengurangi emisi SO₂ dari cerobong asap industri adalah...','[{"key": "A", "text": "Cyclone Separator"}, {"key": "B", "text": "Electrostatic Precipitator (ESP)"}, {"key": "C", "text": "Flue-Gas Desulfurization (FGD)"}, {"key": "D", "text": "Catalytic Converter"}]'::jsonb,'C','Selain emisi dari cerobong asap industri, sumber utama partikulat di lingkungan perkotaan adalah emisi dari knalpot kendaraan, terutama mesin diesel, serta debu dari permukaan jalan, konstruksi, dan tanah yang beterbangan kembali ke udara.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Catalytic converter pada kendaraan bermotor berfungsi untuk mengubah polutan berbahaya seperti CO, NOx, dan hidrokarbon menjadi...','[{"key": "A", "text": "SO₂, H₂S, dan H₂O"}, {"key": "B", "text": "CO₂, N₂, dan H₂O"}, {"key": "C", "text": "O₃, Cl₂, dan CH₄"}, {"key": "D", "text": "CO, N₂, dan O₂"}]'::jsonb,'B','Karbon dioksida adalah gas rumah kaca. Gas ini transparan terhadap radiasi matahari yang masuk, tetapi menyerap radiasi inframerah (panas) yang dipantulkan dari permukaan bumi. Penyerapan ini memerangkap panas di atmosfer, menyebabkan peningkatan suhu rata-rata global, sebuah fenomena yang dikenal sebagai efek rumah kaca atau pemanasan global.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perhitungan emisi polutan dari suatu sumber industri biasanya didasarkan pada...','[{"key": "A", "text": "Warna asap yang keluar"}, {"key": "B", "text": "Faktor emisi dikalikan dengan laju aktivitas (misal, jumlah bahan bakar yang digunakan)"}, {"key": "C", "text": "Suhu cerobong asap"}, {"key": "D", "text": "Jumlah karyawan yang bekerja"}]'::jsonb,'D','Pilihan A, B, dan C adalah strategi mitigasi yang valid untuk mengurangi CO₂. Sebaliknya, penggunaan pupuk nitrogen secara berlebihan justru dapat menyebabkan masalah lingkungan lain, yaitu peningkatan emisi dinitrogen oksida (N₂O), gas rumah kaca yang potensinya jauh lebih kuat daripada CO₂.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Reaksi pembakaran sempurna propana (C₃H₈) yang setara adalah...','[{"key": "A", "text": "C₃H₈ + 3O₂ → 3CO₂ + 4H₂O"}, {"key": "B", "text": "C₃H₈ + 5O₂ → 3CO₂ + 4H₂O"}, {"key": "C", "text": "2C₃H₈ + 7O₂ → 6CO₂ + 8H₂O"}, {"key": "D", "text": "C₃H₈ + O₂ → 3CO + 4H₂O"}]'::jsonb,'A','','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebanyak 2 Liter gas Nitrogen (N₂) direaksikan dengan gas Hidrogen (H₂) menghasilkan Amonia (NH₃) sesuai reaksi N₂(g) + 3H₂(g) → 2NH₃(g). Volume gas Hidrogen yang diperlukan pada suhu dan tekanan yang sama adalah...','[{"key": "A", "text": "2 Liter"}, {"key": "B", "text": "3 Liter"}, {"key": "C", "text": "4 Liter"}, {"key": "D", "text": "6 Liter"}]'::jsonb,'A','','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada reaksi kesetimbangan: 2HI(g) ⇌ H₂(g) + I₂(g), jika konsentrasi HI diperbesar, maka kesetimbangan akan...','[{"key": "A", "text": "Bergeser ke kanan"}, {"key": "B", "text": "Bergeser ke kiri"}, {"key": "C", "text": "Tetap tidak berubah"}, {"key": "D", "text": "Bergeser ke arah endoterm"}]'::jsonb,'A','','AKDING',3);
