  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tetapan kesetimbangan (Kp) untuk reaksi yang melibatkan gas-gas berhubungan dengan tekanan parsial. Untuk reaksi N₂O₄(g) ⇌ 2NO₂(g), rumus Kp yang benar adalah...','[{"key": "A", "text": "Kp = P(NO₂)² / P(N₂O₄)"}, {"key": "B", "text": "Kp = P(N₂O₄) / P(NO₂)²"}, {"key": "C", "text": "Kp = P(NO₂) / P(N₂O₄)"}, {"key": "D", "text": "Kp = [NO₂]² / [N₂O₄]"}]'::jsonb,'A','','AKDING',9);
